/**
 * Long-form case study content.
 *
 * Generated by an agent pipeline that drafted each study from the real `projects`
 * record, then ran it past an adversarial fact-checker. The checker was told to
 * assume the writer padded to hit a word count and to hunt for invented metrics,
 * client names, timelines, team sizes and testimonials.
 *
 * Every study also recorded what it REFUSED to write for lack of data — most
 * commonly testimonials, client company names, delivery timelines and headcount.
 * None of those appear here. If you later obtain a real testimonial or timeline,
 * add it deliberately; do not let it be inferred.
 *
 * Revised 8 Oct 2026 against the claims ledger. Two rules now hold for every
 * study:
 *   - Attribution. Most of these products are not DevoraX client work. Each
 *     summary says who the work was for: "Sameem worked on X as an engineer at
 *     <Employer>", Sameem's own account of his role where the context is
 *     unconfirmed, or "no public link and no named client". Never "DevoraX
 *     built X".
 *   - Figures. No usage, revenue, uptime or satisfaction figure appears unless a
 *     reader can check it today on a store listing or live site. "The client
 *     reports" is not a source. `results` lists only checkable facts (store
 *     listings, release months, live or demo URLs) and is empty when there is
 *     nothing public to check.
 *
 * Rendered server-side so crawlers and AI engines (which do not execute
 * JavaScript) read it from the initial HTML.
 */
export type CaseStudyContent = {
  project_id: number;
  title: string;
  meta_description: string;
  summary_answer: string;
  sections: { heading: string; body: string }[];
  results: string[];
  stack_rationale: string[];
  word_count: number;
  /** ISO date this study was last substantively revised. */
  updated?: string;
};

